function multiply(num1, num2) {
    if (num1 === '0' || num2 === '0') {
        return '0';
    }
    const m = num1.length;
    const n = num2.length;
    const arr = Array(m + n).fill(0);
    for (let i = m - 1; i >= 0; i--) {
        const a = +num1[i];
        for (let j = n - 1; j >= 0; j--) {
            const b = +num2[j];
            arr[i + j + 1] += a * b;
        }
    }
    for (let i = arr.length - 1; i > 0; i--) {
        arr[i - 1] += Math.floor(arr[i] / 10);
        arr[i] %= 10;
    }
    let i = 0;
    while (i < arr.length && arr[i] === 0) {
        i++;
    }
    return arr.slice(i).join('');
}

